# Геттеры и сеттеры

**Геттер (getter)** - вычисляемое свойство для получения значения.
**Сеттер (setter)** - метод для установки значения с валидацией.

## Синтаксис:

```dart
class MyClass {
  // Приватное поле
  String _name;

  // Геттер
  String get name => _name;

  // Сеттер
  set name(String value) {
    if (value.isNotEmpty) {
      _name = value;
    }
  }
}
```

## Зачем нужны?

1. **Валидация данных** - проверяем значения перед установкой
2. **Вычисляемые свойства** - свойства, которые рассчитываются динамически
3. **Инкапсуляция** - контролируем доступ к данным
4. **Обратная совместимость** - можем изменить реализацию без изменения интерфейса

**Примеры →**

pages.codeSnippet:
class Rectangle {
  double _width;
  double _height;

  Rectangle(this._width, this._height);

  // Геттеры
  double get width => _width;
  double get height => _height;

  // Вычисляемые геттеры
  double get area => _width * _height;
  double get perimeter => 2 * (_width + _height);

  // Сеттеры с валидацией
  set width(double value) {
    if (value > 0) {
      _width = value;
    } else {
      print('Ширина должна быть положительной!');
    }
  }

  set height(double value) {
    if (value > 0) {
      _height = value;
    } else {
      print('Высота должна быть положительной!');
    }
  }

  void display() {
    print('Прямоугольник:');
    print('Ширина: $width, Высота: $height');
    print('Площадь: $area');
    print('Периметр: $perimeter');
  }
}

class BankAccount {
  String _accountNumber;
  double _balance;

  BankAccount(this._accountNumber, this._balance);

  // Геттер (только чтение)
  String get accountNumber => _accountNumber;
  double get balance => _balance;

  // Вычисляемый геттер
  String get formattedBalance => '${_balance.toStringAsFixed(2)} ₸';

  // Методы для работы с балансом (вместо сеттера)
  void deposit(double amount) {
    if (amount > 0) {
      _balance += amount;
      print('Пополнено: $amount ₸');
    }
  }

  void withdraw(double amount) {
    if (amount > 0 && amount <= _balance) {
      _balance -= amount;
      print('Снято: $amount ₸');
    } else {
      print('Недостаточно средств!');
    }
  }
}

void main() {
  // Пример с Rectangle
  Rectangle rect = Rectangle(5, 10);
  rect.display();

  print('\nИзменяем размеры:');
  rect.width = 8;
  rect.height = 12;
  rect.display();

  print('\nПопытка установить отрицательное значение:');
  rect.width = -5; // валидация сработает

  // Пример с BankAccount
  print('\n--- Банковский счет ---');
  BankAccount account = BankAccount('KZ123456789', 10000);
  print('Номер счета: ${account.accountNumber}');
  print('Баланс: ${account.formattedBalance}');

  account.deposit(5000);
  print('Новый баланс: ${account.formattedBalance}');

  account.withdraw(3000);
  print('Новый баланс: ${account.formattedBalance}');

  account.withdraw(20000); // недостаточно средств
}

