# Миксины (Mixins)

**Миксин** - способ переиспользования кода класса в нескольких классах без наследования.

Dart не поддерживает множественное наследование, но миксины решают эту проблему!

## Синтаксис:

```dart
// Объявление миксина
mixin MixinName {
  // поля и методы
}

// Использование миксина
class MyClass with Mixin1, Mixin2 {
  // код класса
}
```

## Отличия от наследования:

- Класс может использовать несколько миксинов
- Миксин нельзя создать напрямую (new Mixin())
- Миксин добавляет функциональность без изменения иерархии

## Когда использовать:

- Нужно добавить одинаковую функциональность разным классам
- Классы не связаны иерархически
- Нужно скомбинировать несколько поведений

**Примеры →**

pages.codeSnippet:
// Миксины для добавления возможностей
mixin Flyable {
  double altitude = 0;

  void fly() {
    altitude = 100;
    print('Летит на высоте $altitude метров');
  }

  void land() {
    altitude = 0;
    print('Приземлился');
  }
}

mixin Swimmable {
  double depth = 0;

  void swim() {
    depth = 5;
    print('Плывет на глубине $depth метров');
  }

  void surfaceUp() {
    depth = 0;
    print('Всплыл на поверхность');
  }
}

mixin Walkable {
  void walk() {
    print('Идет по земле');
  }
}

// Базовый класс
class Animal {
  String name;
  Animal(this.name);

  void eat() {
    print('$name ест');
  }
}

// Утка может летать, плавать и ходить
class Duck extends Animal with Flyable, Swimmable, Walkable {
  Duck(String name) : super(name);

  void quack() {
    print('$name крякает: Кря-кря!');
  }
}

// Рыба может только плавать
class Fish extends Animal with Swimmable {
  Fish(String name) : super(name);

  void blowBubbles() {
    print('$name пускает пузыри');
  }
}

// Птица может летать и ходить
class Eagle extends Animal with Flyable, Walkable {
  Eagle(String name) : super(name);

  void hunt() {
    print('$name охотится с высоты!');
  }
}

// Человек может ходить и плавать
class Human extends Animal with Walkable, Swimmable {
  Human(String name) : super(name);

  void talk() {
    print('$name говорит');
  }
}

void main() {
  print('=== УТКА ===');
  Duck duck = Duck('Дональд');
  duck.walk();
  duck.swim();
  duck.fly();
  duck.quack();
  duck.eat();

  print('\n=== РЫБА ===');
  Fish fish = Fish('Немо');
  fish.swim();
  fish.blowBubbles();
  fish.eat();
  // fish.fly(); // ОШИБКА! Рыба не может летать

  print('\n=== ОРЕЛ ===');
  Eagle eagle = Eagle('Беркут');
  eagle.walk();
  eagle.fly();
  eagle.hunt();
  eagle.land();

  print('\n=== ЧЕЛОВЕК ===');
  Human human = Human('Иван');
  human.walk();
  human.swim();
  human.talk();
  human.surfaceUp();
}

