# Абстрактные классы

**Абстрактный класс** - класс, который нельзя создать напрямую. Он служит шаблоном для других классов.

## Особенности:

- Объявляется с ключевым словом `abstract`
- Нельзя создать экземпляр: `new AbstractClass()` - ОШИБКА
- Может содержать абстрактные методы (без реализации)
- Может содержать обычные методы (с реализацией)
- Наследники ДОЛЖНЫ реализовать все абстрактные методы

**Синтаксис:**
```dart
abstract class Shape {
  // Абстрактный метод (без тела)
  double calculateArea();

  // Обычный метод (с телом)
  void display() {
    print('Площадь: ${calculateArea()}');
  }
}
```

## Когда использовать:

- Нужен общий интерфейс для группы классов
- Хотим обеспечить базовую реализацию некоторых методов
- Хотим заставить наследников реализовать определенные методы

**Примеры →**

pages.codeSnippet:
// Абстрактный класс для фигур
abstract class Shape {
  String color;

  Shape(this.color);

  // Абстрактные методы (должны быть реализованы)
  double calculateArea();
  double calculatePerimeter();

  // Обычный метод (уже реализован)
  void displayInfo() {
    print('Цвет: $color');
    print('Площадь: ${calculateArea().toStringAsFixed(2)}');
    print('Периметр: ${calculatePerimeter().toStringAsFixed(2)}');
    print('---');
  }
}

// Класс круга
class Circle extends Shape {
  double radius;

  Circle(String color, this.radius) : super(color);

  @override
  double calculateArea() {
    return 3.14159 * radius * radius;
  }

  @override
  double calculatePerimeter() {
    return 2 * 3.14159 * radius;
  }
}

// Класс прямоугольника
class Rectangle extends Shape {
  double width;
  double height;

  Rectangle(String color, this.width, this.height) : super(color);

  @override
  double calculateArea() {
    return width * height;
  }

  @override
  double calculatePerimeter() {
    return 2 * (width + height);
  }
}

// Класс треугольника
class Triangle extends Shape {
  double a, b, c; // стороны

  Triangle(String color, this.a, this.b, this.c) : super(color);

  @override
  double calculateArea() {
    // Формула Герона
    double s = (a + b + c) / 2;
    return Math.sqrt(s * (s - a) * (s - b) * (s - c));
  }

  @override
  double calculatePerimeter() {
    return a + b + c;
  }
}

import 'dart:math' as Math;

void main() {
  // Shape shape = Shape('красный'); // ОШИБКА! Нельзя создать абстрактный класс

  // Создание конкретных фигур
  Circle circle = Circle('красный', 5);
  Rectangle rectangle = Rectangle('синий', 4, 6);
  Triangle triangle = Triangle('зеленый', 3, 4, 5);

  print('=== КРУГ ===');
  circle.displayInfo();

  print('\n=== ПРЯМОУГОЛЬНИК ===');
  rectangle.displayInfo();

  print('\n=== ТРЕУГОЛЬНИК ===');
  triangle.displayInfo();

  // Полиморфизм - работа с абстрактным типом
  print('\n=== ВСЕ ФИГУРЫ ===');
  List<Shape> shapes = [circle, rectangle, triangle];

  double totalArea = 0;
  for (var shape in shapes) {
    totalArea += shape.calculateArea();
  }

  print('Общая площадь всех фигур: ${totalArea.toStringAsFixed(2)}');
}

// ПРИМЕР: Нарушение vs Соблюдение SOLID

// ❌ ПЛОХО: Класс делает слишком много (нарушает SRP)
class BadUser {
  String name;
  String email;

  BadUser(this.name, this.email);

  // Сохранение в базу данных
  void save() {
    print('Сохранение в БД: $name');
  }

  // Отправка email
  void sendEmail(String message) {
    print('Отправка email на $email: $message');
  }

  // Логирование
  void log(String action) {
    print('[LOG] $name: $action');
  }
}

// ✅ ХОРОШО: Каждый класс имеет одну ответственность
class User {
  String name;
  String email;

  User(this.name, this.email);
}

class UserRepository {
  void save(User user) {
    print('Сохранение в БД: ${user.name}');
  }
}

class EmailService {
  void send(String email, String message) {
    print('Отправка email на $email: $message');
  }
}

class Logger {
  void log(String message) {
    print('[LOG] $message');
  }
}

void main() {
  print('=== ПЛОХОЙ ПОДХОД ===');
  BadUser badUser = BadUser('Иван', 'ivan@example.com');
  badUser.save();
  badUser.sendEmail('Привет!');
  badUser.log('Создан');

  print('\n=== ХОРОШИЙ ПОДХОД ===');
  User user = User('Мария', 'maria@example.com');

  UserRepository repo = UserRepository();
  repo.save(user);

  EmailService emailService = EmailService();
  emailService.send(user.email, 'Добро пожаловать!');

  Logger logger = Logger();
  logger.log('Пользователь ${user.name} создан');

  print('\nПреимущества:');
  print('✓ Каждый класс отвечает за одну вещь');
  print('✓ Легко тестировать каждый компонент отдельно');
  print('✓ Изменения в EmailService не влияют на User');
}

// ❌ ПЛОХО: Класс имеет множество ответственностей
class BadInvoice {
  String customerName;
  double amount;
  List<String> items;

  BadInvoice(this.customerName, this.amount, this.items);

  // Ответственность 1: Расчет
  double calculateTotal() {
    return amount * 1.2; // с НДС
  }

  // Ответственность 2: Форматирование
  String generateHTML() {
    return '<html><body>Счет для $customerName: ${calculateTotal()}</body></html>';
  }

  // Ответственность 3: Сохранение
  void saveToDatabase() {
    print('Сохранение счета в БД...');
  }

  // Ответственность 4: Отправка
  void sendByEmail() {
    print('Отправка счета на email...');
  }
}

// ✅ ХОРОШО: Разделенные ответственности

// Модель данных
class Invoice {
  String customerName;
  double amount;
  List<String> items;

  Invoice(this.customerName, this.amount, this.items);
}

// Калькулятор
class InvoiceCalculator {
  double calculateTotal(Invoice invoice) {
    return invoice.amount * 1.2; // с НДС
  }

