// ❌ ПЛОХО: Квадрат не является правильным наследником Прямоугольника
class BadRectangle {
  double width;
  double height;

  BadRectangle(this.width, this.height);

  double area() => width * height;
}

// Кажется логичным, но нарушает LSP!
class BadSquare extends BadRectangle {
  BadSquare(double side) : super(side, side);

  // Проблема: устанавливая ширину, должны установить и высоту!
  set width(double value) {
    super.width = value;
    super.height = value; // Неожиданное поведение!
  }

  set height(double value) {
    super.width = value; // Неожиданное поведение!
    super.height = value;
  }
}

// ✅ ХОРОШО: Правильная иерархия классов

abstract class Shape {
  double area();
  String describe();
}

class Rectangle extends Shape {
  double width;
  double height;

  Rectangle(this.width, this.height);

  @override
  double area() => width * height;

  @override
  String describe() => 'Прямоугольник ${width}x$height';

  void setWidth(double value) {
    width = value;
  }

  void setHeight(double value) {
    height = value;
  }
}

class Square extends Shape {
  double side;

  Square(this.side);

  @override
  double area() => side * side;

  @override
  String describe() => 'Квадрат ${side}x$side';

  void setSide(double value) {
    side = value;
  }
}

// Функция, работающая с фигурами
void printShapeInfo(Shape shape) {
  print('${shape.describe()}');
  print('Площадь: ${shape.area()}');
  print('---');
}

// ❌ Пример нарушения LSP
class BadBird {
  void fly() {
    print('Птица летит');
  }
}

// Пингвин не может летать!
class Penguin extends BadBird {
  @override
  void fly() {
    throw Exception('Пингвины не летают!'); // Нарушение LSP!
  }
}

// ✅ ХОРОШО: Правильная иерархия
abstract class Bird {
  void eat() {
    print('Птица ест');
  }
}

mixin Flyable {
  void fly() {
    print('Летит в небе');
  }
}

class Sparrow extends Bird with Flyable {
  // Воробей может летать
}

class GoodPenguin extends Bird {
  // Пингвин не умеет летать, и это нормально
  void swim() {
    print('Пингвин плывет');
  }
}

void main() {
  print('=== ПЛОХОЙ ПОДХОД: Квадрат и Прямоугольник ===');
  BadRectangle rect = BadRectangle(4, 5);
  print('Площадь прямоугольника: ${rect.area()}');

  BadSquare square = BadSquare(4);
  print('Площадь квадрата: ${square.area()}');

  // Проблема: ожидаем поведение прямоугольника, получаем квадрат!
  BadRectangle shape = BadSquare(5);
  shape.width = 10; // Изменится и height!
  print('Ожидали 10x5=50, получили: ${shape.area()}'); // 100!

  print('\n=== ХОРОШИЙ ПОДХОД ===');
  // Все фигуры корректно работают через базовый тип
  List<Shape> shapes = [
    Rectangle(4, 5),
    Square(4),
    Rectangle(10, 2),
    Square(7),
  ];

  for (var shape in shapes) {
    printShapeInfo(shape); // Работает предсказуемо для всех!
  }

  print('\n=== ПЛОХО: Птицы ===');
  try {
    BadBird penguin = Penguin();
    penguin.fly(); // Упадет с исключением!
  } catch (e) {
    print('Ошибка: $e');
  }

  print('\n=== ХОРОШО: Птицы ===');
  Sparrow sparrow = Sparrow();
  sparrow.fly();

  GoodPenguin penguin = GoodPenguin();
  penguin.eat();
  penguin.swim(); // У пингвина свои методы

  print('\nПреимущества:');
  print('✓ Наследники не нарушают ожидания от базового класса');
  print('✓ Можно безопасно использовать полиморфизм');
  print('✓ Нет неожиданных исключений');
}

// ❌ ПЛОХО: Огромный интерфейс заставляет реализовывать ненужные методы
abstract class BadWorker {
