// ✅ ХОРОШО: Разделенные интерфейсы

// Базовая работа
abstract class Workable {
  void work();
}

// Биологические потребности
abstract class Biological {
  void eat();
  void sleep();
}

// Для сотрудников
abstract class Employee {
  void getSalary();
  void attendMeeting();
}

// Для устройств
abstract class Rechargeable {
