  }
}

// Робот реализует только то, что ему нужно
class Robot implements Workable, Rechargeable {
  String model;

  Robot(this.model);

  @override
  void work() {
    print('Робот $model работает');
  }

  @override
  void recharge() {
    print('Робот $model заряжается');
  }
