void main() {
  print('=== ПЛОХОЙ ПОДХОД ===');
  try {
    BadRobot badRobot = BadRobot();
    badRobot.work();
    badRobot.eat(); // Упадет!
  } catch (e) {
    print('Ошибка: $e');
    print('Проблема: Робота заставили реализовать ненужные методы!');
  }

  print('\n=== ХОРОШИЙ ПОДХОД ===');

  Human alice = Human('Алиса');
  Robot r2d2 = Robot('R2-D2');
  Intern bob = Intern('Боб');

  WorkManager manager = WorkManager();

  // Можем управлять работой всех, кто умеет работать
  manager.manageWork(alice);
  manager.manageWork(r2d2);
  manager.manageWork(bob);

  // Но только живые едят
  manager.manageBiological(alice);
  manager.manageBiological(bob);
  // manager.manageBiological(r2d2); // ОШИБКА компиляции - и это хорошо!

  print('\n=== Зарплата ===');
  alice.getSalary();
  // bob.getSalary(); // ОШИБКА компиляции - стажер не Employee!

  print('\n=== Зарядка ===');
  r2d2.recharge();
  // alice.recharge(); // ОШИБКА компиляции - человек не Rechargeable!

  print('\nПреимущества:');
  print('✓ Каждый класс реализует только нужные ему методы');
  print('✓ Нет пустых методов или исключений');
  print('✓ Компилятор помогает избежать ошибок');
