  print('\n--- Mock для тестов ---');
  UserService testService = UserService(MockDatabase());
  testService.saveUser('Тестовый пользователь');
  print(testService.getUser('test'));

  print('\n=== КОМБИНИРОВАНИЕ ЗАВИСИМОСТЕЙ ===');

  // Разные комбинации!
  RegistrationService reg1 = RegistrationService(
    MySQLDatabaseImpl(),
    EmailNotifier(),
  );
  reg1.register('Пользователь1');

  RegistrationService reg2 = RegistrationService(
    MongoDatabase(),
    SMSNotifier(),
  );
  reg2.register('Пользователь2');

  RegistrationService reg3 = RegistrationService(
    PostgreSQLDatabase(),
    PushNotifier(),
  );
  reg3.register('Пользователь3');

  print('\nПреимущества:');
  print('✓ Легко заменить MySQL на PostgreSQL или MongoDB');
  print('✓ Можно использовать Mock для тестирования');
  print('✓ UserService не зависит от конкретной БД');
  print('✓ Можно комбинировать разные реализации');
  print('✓ Код стал гибким и расширяемым');
}

