# Обработка ошибок

**try-catch** - механизм обработки ошибок (исключений) в программе.

## Синтаксис:

```dart
try {
  // Код, который может вызвать ошибку
} catch (e) {
  // Обработка ошибки
} finally {
  // Выполняется всегда (опционально)
}
```

## Расширенный catch:

```dart
try {
  // код
} on FormatException catch (e) {
  // Обработка конкретного типа ошибки
} on Exception catch (e, stackTrace) {
  // e - объект ошибки
  // stackTrace - трассировка стека
} catch (e) {
  // Ловим все остальные ошибки
} finally {
  // Всегда выполняется
}
```

## Генерация ошибок:

```dart
throw Exception('Описание ошибки');
throw FormatException('Неверный формат');
throw 'Простая строка-ошибка';
```

**Примеры →**

pages.codeSnippet:
import 'dart:async';

// Функция с разными типами ошибок
Future<int> divide(int a, int b) async {
  await Future.delayed(Duration(milliseconds: 500));

  if (b == 0) {
    throw Exception('Деление на ноль!');
  }
  return a ~/ b;
}

Future<int> parseNumber(String text) async {
  await Future.delayed(Duration(milliseconds: 300));

  if (text.isEmpty) {
    throw FormatException('Пустая строка!');
  }

  int? number = int.tryParse(text);
  if (number == null) {
    throw FormatException('"$text" не является числом');
  }

  return number;
}

Future<void> processData(String input) async {
  if (input.length < 3) {
    throw ArgumentError('Слишком короткий ввод');
  }
  print('Обработка: $input');
}

void main() async {
  // Пример 1: Базовый try-catch
  print('=== Пример 1: Базовый try-catch ===');
  try {
    int result = await divide(10, 2);
    print('10 / 2 = $result');

    result = await divide(10, 0); // Ошибка!
    print('Результат: $result'); // Не выполнится
  } catch (e) {
    print('Ошибка: $e');
  }

  // Пример 2: Обработка разных типов ошибок
  print('\n=== Пример 2: Разные типы ошибок ===');
  try {
    int number = await parseNumber('abc');
    print('Число: $number');
  } on FormatException catch (e) {
    print('Ошибка формата: $e');
  } on Exception catch (e) {
    print('Другая ошибка: $e');
  }

  // Пример 3: try-catch-finally
  print('\n=== Пример 3: finally блок ===');
  try {
    await processData('ab'); // Слишком короткий
  } on ArgumentError catch (e) {
    print('Неверный аргумент: $e');
  } finally {
    print('Блок finally выполнился');
  }

  // Пример 4: Stack trace
  print('\n=== Пример 4: Stack trace ===');
  try {
    await divide(5, 0);
  } catch (e, stackTrace) {
    print('Ошибка: $e');
    print('Stack trace:');
    print(stackTrace);
  }

  // Пример 5: Множественные try-catch
  print('\n=== Пример 5: Цепочка операций ===');
  try {
    int num1 = await parseNumber('10');
    print('Первое число: $num1');

    int num2 = await parseNumber('5');
    print('Второе число: $num2');

    int result = await divide(num1, num2);
    print('Результат: $num1 / $num2 = $result');
  } catch (e) {
    print('Ошибка в процессе: $e');
  } finally {
    print('Завершение операции');
  }

  // Пример 6: Вложенные try-catch
  print('\n=== Пример 6: Вложенные try-catch ===');
  try {
    try {
      await divide(10, 0);
    } catch (e) {
      print('Внутренний catch: $e');
      throw Exception('Повторная ошибка'); // Пробрасываем дальше
    }
  } catch (e) {
    print('Внешний catch: $e');
  }

  print('\nПрограмма завершена успешно!');
}

import 'dart:async';

// Простой генератор Stream
Stream<int> countStream(int max) async* {
  for (int i = 1; i <= max; i++) {
    await Future.delayed(Duration(milliseconds: 500));
    yield i; // Отправляем значение в Stream
  }
}

// Stream с разными типами данных
Stream<String> messageStream() async* {
  yield 'Привет';
  await Future.delayed(Duration(seconds: 1));
  yield 'Как дела?';
  await Future.delayed(Duration(seconds: 1));
  yield 'До свидания!';
}

// Stream с ошибкой
Stream<int> streamWithError() async* {
  yield 1;
  yield 2;
  throw Exception('Ошибка в потоке!');
  yield 3; // Не выполнится
}

void main() async {
  // Пример 1: await for
  print('=== Пример 1: await for ===');
  await for (var number in countStream(5)) {
    print('Получено: $number');
  }
  print('Счет завершен');

  // Пример 2: listen()
  print('\n=== Пример 2: listen() ===');
  StreamSubscription subscription = countStream(3).listen(
    (number) {
      print('Событие: $number');
    },
    onDone: () {
      print('Stream завершен');
    },
    onError: (error) {
      print('Ошибка: $error');
    },
  );

  // Ждем завершения
  await Future.delayed(Duration(seconds: 2));

  // Пример 3: Преобразование данных
  print('\n=== Пример 3: map() и where() ===');
  await for (var number in countStream(10)
      .where((n) => n % 2 == 0)  // Только четные
      .map((n) => n * 10)) {     // Умножаем на 10
    print('Обработано: $number');
  }

  // Пример 4: take()
  print('\n=== Пример 4: take() ===');
  await for (var number in countStream(100).take(3)) {
    print('Взято: $number'); // Возьмет только 3 первых
  }

  // Пример 5: Stream.periodic
  print('\n=== Пример 5: periodic ===');
  Stream<int> periodic = Stream.periodic(
    Duration(milliseconds: 300),
    (count) => count,
  ).take(5);

  await for (var tick in periodic) {
    print('Тик: $tick');
  }

  // Пример 6: Обработка ошибок
  print('\n=== Пример 6: Ошибки в Stream ===');
  try {
    await for (var number in streamWithError()) {
      print('Число: $number');
    }
  } catch (e) {
    print('Поймана ошибка: $e');
  }

  // Пример 7: Строковый Stream
  print('\n=== Пример 7: Сообщения ===');
  await for (var message in messageStream()) {
    print('Сообщение: $message');
  }

  print('\nВсе примеры выполнены!');
}

import 'dart:async';

// Модель пользователя
class User {
  final String id;
  String name;
  String email;
  int age;

  User({
    required this.id,
    required this.name,
    required this.email,
    required this.age,
  });

  // Именованный конструктор из Map (для JSON)
  User.fromMap(Map<String, dynamic> map)
      : id = map['id'],
        name = map['name'],
        email = map['email'],
        age = map['age'];

  // Преобразование в Map (для JSON)
  Map<String, dynamic> toMap() {
    return {
      'id': id,
      'name': name,
      'email': email,
      'age': age,
    };
  }

  @override
  String toString() {
    return 'User(id: $id, name: $name, email: $email, age: $age)';
  }
}

// Репозиторий для работы с данными
class UserRepository {
  // Симуляция базы данных
  final Map<String, User> _database = {};

  // Создание пользователя
  Future<User> createUser(User user) async {
    await Future.delayed(Duration(seconds: 1));
    _database[user.id] = user;
    print('✓ Пользователь создан: ${user.name}');
    return user;
  }

  // Получение пользователя
  Future<User?> getUser(String id) async {
    await Future.delayed(Duration(milliseconds: 500));
    return _database[id];
  }

  // Получение всех пользователей
  Future<List<User>> getAllUsers() async {
    await Future.delayed(Duration(milliseconds: 800));
    return _database.values.toList();
  }

  // Обновление пользователя
  Future<User> updateUser(User user) async {
    await Future.delayed(Duration(milliseconds: 500));
    if (!_database.containsKey(user.id)) {
      throw Exception('Пользователь не найден');
    }
    _database[user.id] = user;
    print('✓ Пользователь обновлен: ${user.name}');
    return user;
  }

  // Удаление пользователя
  Future<void> deleteUser(String id) async {
    await Future.delayed(Duration(milliseconds: 500));
    _database.remove(id);
    print('✓ Пользователь удален: $id');
  }
}

// Сервис для бизнес-логики
class UserService {
  final UserRepository _repository;
  final StreamController<String> _eventController = StreamController.broadcast();

  UserService(this._repository);

  // Stream событий
  Stream<String> get events => _eventController.stream;

  // Регистрация пользователя
  Future<User> registerUser(String name, String email, int age) async {
    try {
      _eventController.add('Регистрация пользователя $name...');

      // Валидация
      if (name.isEmpty) {
        throw ArgumentError('Имя не может быть пустым');
      }
      if (!email.contains('@')) {
        throw ArgumentError('Неверный email');
      }
      if (age < 0) {
        throw ArgumentError('Возраст не может быть отрицательным');
      }

      // Создание пользователя
      String id = 'user_${DateTime.now().millisecondsSinceEpoch}';
      User user = User(id: id, name: name, email: email, age: age);

      await _repository.createUser(user);
      _eventController.add('Пользователь $name зарегистрирован');

      return user;
    } catch (e) {
      _eventController.add('Ошибка регистрации: $e');
      rethrow;
    }
  }

  // Получение информации о пользователе
  Future<String> getUserInfo(String id) async {
    User? user = await _repository.getUser(id);
    if (user == null) {
      return 'Пользователь не найден';
    }
    return '${user.name} (${user.email}), ${user.age} лет';
  }

  // Список всех пользователей
  Future<void> listAllUsers() async {
    List<User> users = await _repository.getAllUsers();
    print('\n=== Список пользователей (${users.length}) ===');
    for (var user in users) {
      print('- ${user.name} (${user.email})');
    }
  }

  void dispose() {
    _eventController.close();
  }
}

void main() async {
  // Создание сервиса
  UserRepository repository = UserRepository();
  UserService service = UserService(repository);

  // Подписка на события
  service.events.listen((event) {
    print('📢 Событие: $event');
  });

  print('=== Система управления пользователями ===\n');

  try {
    // Регистрация пользователей
    User user1 = await service.registerUser('Алиса', 'alice@example.com', 25);
    User user2 = await service.registerUser('Боб', 'bob@example.com', 30);
    User user3 = await service.registerUser('Карл', 'carl@example.com', 28);

    // Список пользователей
    await service.listAllUsers();

    // Получение информации
    print('\n=== Информация о пользователе ===');
    String info = await service.getUserInfo(user1.id);
    print(info);

    // Обновление пользователя
    print('\n=== Обновление ===');
    user1.age = 26;
    await repository.updateUser(user1);

    // Попытка создать пользователя с невалидными данными
    print('\n=== Попытка невалидной регистрации ===');
    try {
      await service.registerUser('', 'invalid', -5);
    } catch (e) {
      print('Ошибка поймана: $e');
    }

    // Удаление пользователя
    print('\n=== Удаление ===');
    await repository.deleteUser(user2.id);

    // Финальный список
    await service.listAllUsers();

  } catch (e) {
    print('Произошла ошибка: $e');
  } finally {
    service.dispose();
    print('\nСервис остановлен');
  }
}
